import random, json
random.seed(0)
def rom(n):
    out='';
    for v,s in [(10,'X'),(9,'IX'),(5,'V'),(4,'IV'),(1,'I')]:
        while n>=v: out+=s; n-=v
    return out
items=[];control=[]
